    function checkUnmatchedJSDocParameters(node: SignatureDeclaration) {
        const jsdocParameters = filter(getJSDocTags(node), isJSDocParameterTag);
        if (!length(jsdocParameters)) return;

        const isJs = isInJSFile(node);
        const parameters = new Set<string>();
        const parametersByName = new Map<string, ParameterDeclaration>();
        const excludedParameters = new Set<number>();
        forEach(node.parameters, (param, index) => {
            const { name } = param;
            if (name && isIdentifier(name)) {
                parameters.add(name.text);
                parametersByName.set(name.text, param);
            }
            if (name && isBindingPattern(name)) {
                excludedParameters.add(index);
            }
        });

        // An inline closure has no parameter list to walk -- `$1`..`$N` are its parameters,
        // synthesized from the body -- so `@param $1` would look unmatched. Seed the names, but
        // deliberately not `parametersByName`: that map is keyed to real ParameterDeclarations
        // for the type and ref-modifier checks below, which a synthesized symbol cannot satisfy.
        if (isInlineClosureExpression(node)) {
            for (const parameter of getInlineClosureParameters(node)) {
                parameters.add(parameter.name as string);
            }
        }

        const containsArguments = containsArgumentsReference(node);
        if (containsArguments) {
            const lastJSDocParamIndex = jsdocParameters.length - 1;
            const lastJSDocParam = jsdocParameters[lastJSDocParamIndex];
            if (
                isJs && lastJSDocParam && isIdentifier(lastJSDocParam.name) && lastJSDocParam.typeExpression &&
                lastJSDocParam.typeExpression.type && !parameters.has(lastJSDocParam.name.text) && !excludedParameters.has(lastJSDocParamIndex) && !isArrayType(getTypeFromTypeNode(lastJSDocParam.typeExpression.type))
            ) {
                error(lastJSDocParam.name, Diagnostics.JSDoc_param_tag_has_name_0_but_there_is_no_parameter_with_that_name_It_would_match_arguments_if_it_had_an_array_type, idText(lastJSDocParam.name));
            }
        }
        else {
            forEach(jsdocParameters, ({ name, isNameFirst }, index) => {
                if (excludedParameters.has(index) || isIdentifier(name) && parameters.has(name.text)) {
                    return;
                }
                if (isQualifiedName(name)) {
                    if (isJs) {
                        error(name, Diagnostics.Qualified_name_0_is_not_allowed_without_a_leading_param_object_1, entityNameToString(name), entityNameToString(name.left));
                    }
                }
                else {
                    if (!isNameFirst) {
                        errorOrSuggestion(isJs, name, Diagnostics.JSDoc_param_tag_has_name_0_but_there_is_no_parameter_with_that_name, idText(name));
                    }
                }
            });
        }

        // Check JSDoc param types and ref modifiers against actual parameter declarations
        forEach(jsdocParameters, (jsdocParam) => {
            if (!isIdentifier(jsdocParam.name)) return;
            const actualParam = parametersByName.get(jsdocParam.name.text);
            if (!actualParam) return;

            // Check type compatibility: JSDoc type must be assignable to the declared type
            // (JSDoc may narrow e.g. mapping to ([ string: int ]), or object to object "file.c")
            if (jsdocParam.typeExpression && actualParam.type) {
                const jsdocType = getTypeFromTypeNode(jsdocParam.typeExpression.type);
                const paramType = getTypeFromTypeNode(actualParam.type);
                if (!isTypeAssignableTo(jsdocType, paramType) && !isTypeAssignableTo(paramType, jsdocType)) {
                    error(
                        jsdocParam.typeExpression,
                        Diagnostics.LPCDoc_param_tag_has_type_0_but_parameter_has_type_1,
                        typeToString(jsdocType),
                        idText(jsdocParam.name),
                        typeToString(paramType),
                    );
                }
            }

            // Check ref modifier consistency
            const actualIsRef = !!actualParam.ampToken;
            const docIsRef = !!jsdocParam.isRef;
            if (docIsRef && !actualIsRef) {
                error(jsdocParam.name, Diagnostics.LPCDoc_param_tag_has_ref_modifier_but_parameter_0_is_not_pass_by_reference, idText(jsdocParam.name));
            }
            else if (!docIsRef && actualIsRef) {
                error(jsdocParam.name, Diagnostics.LPCDoc_param_tag_is_missing_ref_modifier_but_parameter_0_is_pass_by_reference, idText(jsdocParam.name));
            }
        });
    }

