    interface InlineClosureNodeLinks extends NodeLinks {
        contextualSignatureInferenceContext?: InferenceContext;
        /** Synthesized `$1`..`$N` parameters, in order. Empty if the body uses none. */
        closureParameters?: Symbol[];
        /** `$N` references in the body, bucketed by position. */
        closureParameterReferences?: Identifier[][];
    }

    interface ClosureParameterSymbolLinks extends SymbolLinks {
        closureDeclaration?: InlineClosureExpression;
        closureParameterIndex?: number;
    }

    /**
     * The 1-based index of an inline-closure implicit parameter reference (`$1` -> 1), or 0 if
     * the identifier isn't one. Unlike a TypeScript arrow function, an LPC inline closure has no
     * parameter list -- `$1`..`$9` are ordinary identifiers that the driver binds positionally.
     */
    function getInlineClosureParameterIndex(node: Node): number {
        if (!isIdentifier(node) || node.text.charCodeAt(0) !== CharacterCodes.$) {
            return 0;
        }
        const match = /^\$(\d+)$/.exec(node.text);
        return match ? Number.parseInt(match[1], 10) : 0;
    }

    /**
     * Every `$N` referenced directly by this closure's body, bucketed by position (index 0 holds
     * the `$1` references). A nested `(: ... :)` rebinds `$1`..`$9`, so the walk stops there --
     * the nearest enclosing closure owns them, which is the rule the `$N` lookups have always
     * used. The array's length is the closure's arity; a position the body skips gets an empty
     * bucket, since `(: $2 :)` still takes two arguments.
     */
    function getInlineClosureParameterReferences(node: InlineClosureExpression): Identifier[][] {
        const links = getNodeLinks(node) as InlineClosureNodeLinks;
        if (!links.closureParameterReferences) {
            const references: Identifier[][] = [];
            const visit = (child: Node): void => {
                if (isInlineClosureExpression(child)) {
                    return;
                }
                const index = getInlineClosureParameterIndex(child);
                if (index > 0) {
                    (references[index - 1] ??= []).push(child as Identifier);
                }
                forEachChild(child, visit);
            };
            const body = node.body as Node | NodeArray<Expression> | undefined;
            if (isArray(body)) {
                (body as NodeArray<Expression>).forEach(visit);
            }
            else if (body) {
                visit(body as Node);
            }
            for (let i = 0; i < references.length; i++) {
                references[i] ??= [];
            }
            links.closureParameterReferences = references;
        }
        return links.closureParameterReferences;
    }

    /**
     * Real parameter symbols for a closure's `$1`..`$N`, so the closure gets a `Signature` with
     * an honest arity instead of an empty one. Their types stay lazy -- see
     * `getTypeOfClosureParameter` -- because resolving a contextual signature here would recurse
     * back through the call whose arguments we are in the middle of resolving.
     */
    function getInlineClosureParameters(node: InlineClosureExpression): Symbol[] {
        const links = getNodeLinks(node) as InlineClosureNodeLinks;
        if (!links.closureParameters) {
            const count = getInlineClosureParameterReferences(node).length;
            const parameters: Symbol[] = [];
            for (let i = 0; i < count; i++) {
                const symbol = createSymbol(SymbolFlags.FunctionScopedVariable, `$${i + 1}` as string, CheckFlags.ClosureParameter);
                const symbolLinks = symbol.links as ClosureParameterSymbolLinks;
                symbolLinks.closureDeclaration = node;
                symbolLinks.closureParameterIndex = i;
                parameters.push(symbol);
            }
            links.closureParameters = parameters;
        }
        return links.closureParameters;
    }

    /**
     * What a single use of `$N` tells us about its type. Only argument position is read: LPC's
     * operators are overloaded across so many types (`+` alone spans int, float, string, array
     * and mapping) that inferring from them would invent a narrow type the driver never
     * promised, and every downstream error built on it would be a false positive.
     */
    function getInlineClosureParameterTypeFromUse(reference: Identifier): Type | undefined {
        const parent = reference.parent;
        if (!parent || !isCallExpression(parent) || parent.expression === reference) {
            return undefined;
        }
        const argumentIndex = parent.arguments?.indexOf(reference) ?? -1;
        if (argumentIndex < 0) {
            return undefined;
        }
        // Deliberately not getResolvedSignature: overload resolution needs the types of the
        // call's arguments, and this reference is one of them. Reading the callee's declared
        // signature instead keeps the inference one-directional. A callee with more than one
        // signature is skipped rather than guessed at.
        const callee = parent.expression;
        if (!isIdentifier(callee)) {
            return undefined;
        }
        const calleeSymbol = resolveName(
            callee,
            callee,
            SymbolFlags.Function | SymbolFlags.Value,
            /*nameNotFoundMessage*/ undefined,
            /*isUse*/ false,
            /*excludeGlobals*/ false,
        );
        if (!calleeSymbol) {
            return undefined;
        }
        const signatures = getSignaturesOfType(getTypeOfSymbol(calleeSymbol), SignatureKind.Call);
        return signatures.length === 1 ? tryGetTypeAtPosition(signatures[0], argumentIndex) : undefined;
    }

    /**
     * Infer `$N`'s type from how the body uses it. Uses that resolve to `mixed` -- a variadic
     * `mixed arg ...` parameter, say -- carry no information and are skipped, so a more specific
     * use elsewhere can still win. Uses that disagree fall back to `mixed` rather than
     * intersecting: a wrong narrow type here would surface as a spurious error at the call site.
     */
    function getInlineClosureParameterTypeFromUsage(closure: InlineClosureExpression, index: number): Type | undefined {
        const references = getInlineClosureParameterReferences(closure)[index];
        let candidate: Type | undefined;
        for (const reference of references ?? emptyArray) {
            const type = getInlineClosureParameterTypeFromUse(reference);
            if (!type || isTypeAny(type)) {
                continue;
            }
            if (!candidate) {
                candidate = type;
            }
            else if (candidate !== type) {
                return undefined;
            }
        }
        return candidate;
    }

    function getTypeOfClosureParameter(symbol: Symbol): Type {
        const links = getSymbolLinks(symbol) as ClosureParameterSymbolLinks;
        if (links.type) {
            return links.type;
        }
        const closure = links.closureDeclaration;
        const index = links.closureParameterIndex ?? 0;
        if (!closure) {
            return mixedType;
        }
        // Inferring from usage means resolving the callees the body passes `$N` to, and one of
        // those can lead back here. Report `mixed` for the re-entrant request rather than
        // caching it -- the outer request still gets to record the real answer.
        if (!pushTypeResolution(symbol, TypeSystemPropertyName.Type)) {
            return mixedType;
        }
        // A contextual signature -- `filter(arr, (: $1 > 0 :))` -- is the caller telling us
        // outright, so it outranks anything we could deduce from the body.
        const contextualSignature = getInlineClosureContextualSignature(closure);
        const type = (contextualSignature && tryGetTypeAtPosition(contextualSignature, index))
            || getInlineClosureParameterTypeFromUsage(closure, index)
            || mixedType;
        popTypeResolution();
        return links.type ??= type;
    }

    /** The parameter type for `$index` (1-based) of the closure enclosing `node`, if any. */
    function getTypeOfInlineClosureParameterReference(node: Node, index: number): Type | undefined {
        const closure = findAncestor(node, isInlineClosureExpression);
        if (!closure) {
            return undefined;
        }
        const parameters = getInlineClosureParameters(closure);
        const parameter = parameters[index - 1];
        return parameter && getTypeOfSymbol(parameter);
    }

    function ensureInlineClosureContext(node: InlineClosureExpression): InlineClosureNodeLinks {
        const links = getNodeLinks(node) as InlineClosureNodeLinks;
        if (!links.contextualSignature) {
            const contextualSignature = getContextualSignature(node);
            if (contextualSignature) {
                links.contextualSignature = contextualSignature;
            }
        }
        if (links.contextualSignature && !links.contextualSignatureInferenceContext) {
            const inferenceContext = getInferenceContext(node);
            if (inferenceContext) {
                links.contextualSignatureInferenceContext = inferenceContext;
            }
        }
        return links;
    }

    function getInlineClosureContextualSignature(node: InlineClosureExpression): Signature | undefined {
        const links = ensureInlineClosureContext(node);
        const contextualSignature = links.contextualSignature;
        if (!contextualSignature) {
            return undefined;
        }
        const inferenceContext = links.contextualSignatureInferenceContext;
        return inferenceContext ? instantiateSignature(contextualSignature, inferenceContext.mapper) : contextualSignature;
    }

    function checkLambdaIdentifierExpression(node: LambdaIdentifierExpression, checkMode: CheckMode | undefined): Type {
        // The `#'1` form names the same implicit parameter as `$1`, so it reads the type off the
        // enclosing closure's signature rather than repeating the contextual-signature lookup.
        const name = node.name;
        if (name && name.kind === SyntaxKind.Identifier) {
            const index = Number.parseInt((name as Identifier).text, 10);
            if (!Number.isNaN(index) && index > 0) {
                const parameterType = getTypeOfInlineClosureParameterReference(node, index);
                if (parameterType) {
                    return parameterType;
                }
            }
        }

        // `$<identifier>` (non-numeric) and `$::foo` forms aren't currently typed; treat as mixed.
        return anyType;
    }

    function checkLambdaOperatorExpression(_node: LambdaOperatorExpression, _checkMode: CheckMode | undefined): Type {
        // Operator closures (e.g. `$+`) are currently treated as untyped.
        return anyType;
    }

    function checkRangeExpression(node: RangeExpression, checkMode?: CheckMode): Type {
        const rangeTypes: Type[] = [];
        if (node.left) rangeTypes.push(checkExpression(node.left, checkMode));
        if (node.right) rangeTypes.push(checkExpression(node.right, checkMode));

        return rangeTypes.length > 1 ? getUnionType(rangeTypes, UnionReduction.Subtype) : rangeTypes[0];        
    }

    function checkConditionalExpression(node: ConditionalExpression, checkMode?: CheckMode): Type {
        const type = checkTruthinessExpression(node.condition, checkMode);
        checkTestingKnownTruthyCallableOrAwaitableOrEnumMemberType(node.condition, type, node.whenTrue);
        const type1 = checkExpression(node.whenTrue, checkMode);
        const type2 = checkExpression(node.whenFalse, checkMode);
        return getUnionType([type1, type2], UnionReduction.Subtype);
    }

    function checkDeprecatedSignature(signature: Signature, node: CallLikeExpression) {
        if (signature.flags & SignatureFlags.IsSignatureCandidateForOverloadFailure) return;
        if (signature.declaration && signature.declaration.flags & NodeFlags.Deprecated) {            
            const suggestionNode = getDeprecatedSuggestionNode(node);
            const name = tryGetPropertyAccessOrIdentifierToString(getInvokedExpression(node));
            addDeprecatedSuggestionWithSignature(suggestionNode, signature.declaration, name, signatureToString(signature));
        }
    }

    function addDeprecatedSuggestionWithSignature(location: Node, declaration: Node, deprecatedEntity: string | undefined, signatureString: string) {
        const diagnostic = deprecatedEntity
            ? createDiagnosticForNode(location, Diagnostics.The_signature_0_of_1_is_deprecated, signatureString, deprecatedEntity)
            : createDiagnosticForNode(location, Diagnostics._0_is_deprecated, signatureString);
        return addDeprecatedSuggestionWorker(declaration, diagnostic);
    }

    /**
     * Tries to resolve a string literal node as an object. Will return the object's type if found, or undefined if not.
     * @param stringNode String literal node
     * @param location Optional location node 
     * @returns 
     */
    function tryResolveStringToObject(stringNode: StringLiteral, location?: Node): Type | undefined {
        const specifier = stringNode;
        const locationNode = location || stringNode;
        
        const moduleSymbol = resolveExternalModuleName(locationNode, specifier, undefined);
        if (moduleSymbol) {            
            const objectSymbol = resolveExternalObjectSymbol(moduleSymbol, specifier, /*dontResolveAlias*/ true);
            if (objectSymbol && isSourceFile(objectSymbol.valueDeclaration)) {                
                const objectType = getTypeOfSymbol(objectSymbol);
                return objectType;                
            }           
        }
    }

    function checkCloneObjectExpression(node: CloneObjectExpression | NewExpression, checkMode?: CheckMode): Type {
        checkGrammarImportCallExpression(node);

        if (!node.arguments?.length) {
            // this is an error but we'll return a type anyway
            return anyType;
        }

        const specifier = node.arguments[0];
        const specifierType = checkExpressionCached(specifier);
        
        // type-check extra arguments for completion
        for (let i = 1; i < node.arguments.length; ++i) {
            checkExpressionCached(node.arguments[i]);
        }

        if (specifierType.flags & TypeFlags.Undefined || specifierType.flags & TypeFlags.Null || !isTypeAssignableTo(specifierType, stringType)) {
            error(specifier, Diagnostics.Clone_object_s_specifier_must_be_of_type_string_but_here_has_type_0, typeToString(specifierType));
        }

        // resolveExternalModuleName will return undefined if the moduleReferenceExpression is not a string literal
        const moduleSymbol = resolveExternalModuleName(node, specifier, specifierType);
        if (moduleSymbol) {            
            const objectSymbol = resolveExternalObjectSymbol(moduleSymbol, specifier, /*dontResolveAlias*/ true);
            if (objectSymbol && isSourceFile(objectSymbol.valueDeclaration)) {                
                const objectType = getTypeOfSymbol(objectSymbol);
                return objectType;                
            }           
        }

        // grammar is valid but could not find the module.
        // return anyType to keep things flowing.
        return anyType;
    }

    function resolveExternalObjectSymbol(moduleSymbol: Symbol|undefined, referencingLocation: Node, dontResolveAlias: boolean): Symbol | undefined {
        const symbol = resolveExternalModuleSymbol(moduleSymbol);

        if (!dontResolveAlias && symbol) {            
            Debug.fail("TODO - implement me - resolveExternalObjectSymbol");
        }

        return symbol;
    }    

    function checkGrammarImportCallExpression(node: CloneObjectExpression | NewExpression): boolean {
        const nodeArguments = node.arguments;
        if (nodeArguments?.length === 0) {
            return grammarErrorOnNode(node, Diagnostics.Clone_object_can_only_accept_an_object_name_and_an_optional_set_of_attributes_as_arguments_1450);
        }
    }

    /**
     * Syntactically and semantically checks a call or new expression.
     * @param node The call/new expression to be checked.
     * @returns On success, the expression's signature's return type. On failure, anyType.
     */
    function checkCallExpression(node: CallExpression | NewExpression, checkMode?: CheckMode): Type {
        //checkGrammarTypeArguments(node, node.typeArguments);

        const signature = getResolvedSignature(node, /*candidatesOutArray*/ undefined, checkMode);
        if (signature === resolvingSignature) {
            // CheckMode.SkipGenericFunctions is enabled and this is a call to a generic function that
            // returns a function type. We defer checking and return silentNeverType.
            return silentNeverType;
        }

        checkDeprecatedSignature(signature, node);

        if (node.expression && isNewExpression(node) && isStructTypeNode(node.expression)) {
            // fluff-style new(class foo) syntax
            checkSourceElement(node.expression);
            return getTypeFromTypeNode(node.expression);
        }
        if (isNewExpression(node) && !node.expression && node.arguments?.length) {
            return checkCloneObjectExpression(node);
        }
        if (isCallExpression(node)) {            
            if (node.expression.kind === SyntaxKind.SuperKeyword) {
                return voidType;
            }
            
            const fnName = getNameOfDeclaration(node.expression);                        
            const nameStr = fnName && isIdentifier(fnName) ? fnName.text : undefined;
            if (nameStr === "this_object") {
                // this_object() is a special case that should return the type of the parent sourcefile
                const file = getSourceFileOfNode(node);
                const thisObjectPragmas = file.pragmas.get("this-object") ?? file.pragmas.get("this_object");
                let resultType: Type;

                // if a pragma is found, use the first pragma value as the type
                if (thisObjectPragmas) {
                    const stringLiteral = thisObjectPragmaToStringLiteral(file, thisObjectPragmas);                    
                    resultType = stringLiteral.text?.length ? tryResolveStringToObject(stringLiteral) : undefined;
                }

                if (!resultType) {
                    const sourceFileSymbol = getSymbolAtLocation(file);                    
                    resultType = getTypeOfSymbol(sourceFileSymbol);
                    // resultType = firstOrUndefined(resolveBaseTypeOfSourceFile(getTypeOfSymbol(sourceFileSymbol) as InterfaceType, file));
                }

                return resultType;
            } else if (nameStr === "base_name" && !node.arguments?.length) { 
                // only return the base name of the current file is args is 0
                const file = getSourceFileOfNode(node);
                const basePath = getLibRootedFileName(file.fileName, compilerOptions);                
                return getStringLiteralType(basePath);
            }
           
            // I don't think this is needed anymore since error() was added to binder
            // if (signature.declaration && !(checkMode || 0 & CheckMode.TypeOnly)) {
            //     // check if the function has a return type of error
            //     // we'll use this to mark efuns (like fluff's `error`) that stop execution
            //     // and should be treated as an explicit return
            //     const throwsTag = getJSDocThrowsTag(signature.declaration);
            //     if (throwsTag) {
            //         const fn = getContainingFunction(node);
            //         (fn as Mutable<Node>).flags |= NodeFlags.HasExplicitReturn;
            //     }
            // }        
            
            // evaluate $() args will not checked via call expression resolution
            // so manually check them here.
            if (nameStr === "$" && languageVariant === LanguageVariant.FluffOS && findAncestor(node, isInlineClosureExpression)) {
                const args = node.arguments || emptyArray;                
                                                
                // the first arg should be an identifier pointing at a function
                const fnIdentifier = firstOrUndefined(args);
                if (fnIdentifier && isIdentifier(fnIdentifier)) {
                    const fnType = checkExpressionCached(fnIdentifier, checkMode && checkMode & ~CheckMode.SkipGenericFunctions);   
                    // check args 2+
                    for (let i = 1; i < args.length; ++i) {
                        checkExpression(args[i]);
                    }
                    
                    return fnType;
                }

                args.forEach(a => checkExpression(a));
                return anyType;
            }
        }

        const returnType = getReturnTypeOfSignature(signature);
        // Treat any call to the global 'Symbol' function that is part of a const variable or readonly property
        // as a fresh unique symbol literal type.
        // if (returnType.flags & TypeFlags.ESSymbolLike && isSymbolOrSymbolForCall(node)) {
        //     return getESSymbolLikeTypeForNode(walkUpParenthesizedExpressions(node.parent));
        // }
        if (
            node.kind === SyntaxKind.CallExpression && node.parent.kind === SyntaxKind.ExpressionStatement &&
            returnType.flags & TypeFlags.Void && getTypePredicateOfSignature(signature)
        ) {
            if (!isDottedName(node.expression)) {
                error(node.expression, Diagnostics.Assertions_require_the_call_target_to_be_an_identifier_or_qualified_name);
            }
            else if (!getEffectsSignature(node)) {
                const diagnostic = error(node.expression, Diagnostics.Assertions_require_every_name_in_the_call_target_to_be_declared_with_an_explicit_type_annotation);
                getTypeOfDottedName(node.expression, diagnostic);
            }
        }

        // if (isInJSFile(node)) {
        //     const jsSymbol = getSymbolOfExpando(node, /*allowDeclaration*/ false);
        //     if (jsSymbol?.exports?.size) {
        //         const jsAssignmentType = createAnonymousType(jsSymbol, jsSymbol.exports, emptyArray, emptyArray, emptyArray);
        //         jsAssignmentType.objectFlags |= ObjectFlags.JSLiteral;
        //         return getIntersectionType([returnType, jsAssignmentType]);
        //     }
        // }

        return returnType;
    }
    
    function checkPostfixUnaryExpression(node: PostfixUnaryExpression): Type {
        const operandType = checkExpression(node.operand);
        if (operandType === silentNeverType) {
            return silentNeverType;
        }
        const ok = checkArithmeticOperandType(
            node.operand,
            checkNonNullType(operandType, node.operand),
            Diagnostics.An_arithmetic_operand_must_be_of_type_any_number_bigint_or_an_enum_type,
        );
        if (ok) {
            // run check only if former checks succeeded to avoid reporting cascading errors
            checkReferenceExpression(
                node.operand,
                Diagnostics.The_operand_of_an_increment_or_decrement_operator_must_be_a_variable_or_a_property_access,
                Diagnostics.The_operand_of_an_increment_or_decrement_operator_may_not_be_an_optional_property_access,
            );
        }
        return getUnaryResultType(operandType);
    }

    function getFreshTypeOfLiteralType(type: Type): Type {
        if (type.flags & TypeFlags.Freshable) {
            if (!(type as FreshableType).freshType) {
                const freshType = createLiteralType(type.flags, (type as LiteralType).value, (type as LiteralType).symbol, type as LiteralType);
                freshType.freshType = freshType;
                (type as FreshableType).freshType = freshType;
            }
            return (type as FreshableType).freshType;
        }
        return type;
    }
    
    function maybeTypeOfKindConsideringBaseConstraint(type: Type, kind: TypeFlags): boolean {
        if (maybeTypeOfKind(type, kind)) {
            return true;
        }

        const baseConstraint = getBaseConstraintOrType(type);
        return !!baseConstraint && maybeTypeOfKind(baseConstraint, kind);
    }
    
    /**
     * This is similar to `getBaseConstraintOfType` except it returns the input type if there's no base constraint, instead of `undefined`
     * It also doesn't map indexes to `string`, as where this is used this would be unneeded (and likely undesirable)
     */
    function getBaseConstraintOrType(type: Type) {
        return getBaseConstraintOfType(type) || type;
    }


    function checkPrefixUnaryExpression(node: PrefixUnaryExpression): Type {
        const operandType = checkExpression(node.operand);
        if (operandType === silentNeverType) {
            return silentNeverType;
        }
        switch (node.operand.kind) {
            case SyntaxKind.IntLiteral:
                switch (node.operator) {
                    case SyntaxKind.MinusToken:
                        return getFreshTypeOfLiteralType(getNumberLiteralType(-(node.operand as IntLiteral).text));
                    case SyntaxKind.PlusToken:
                        return getFreshTypeOfLiteralType(getNumberLiteralType(+(node.operand as IntLiteral).text));
                }
                break;
            case SyntaxKind.FloatLiteral:
                switch (node.operator) {
                    case SyntaxKind.MinusToken:
                        return getFreshTypeOfLiteralType(getNumberLiteralType(-(node.operand as FloatLiteral).text));
                    case SyntaxKind.PlusToken:
                        return getFreshTypeOfLiteralType(getNumberLiteralType(+(node.operand as FloatLiteral).text));
                }
        }
        switch (node.operator) {
            case SyntaxKind.PlusToken:
            case SyntaxKind.MinusToken:
            case SyntaxKind.TildeToken:
                checkNonNullType(operandType, node.operand);
                // if (maybeTypeOfKindConsideringBaseConstraint(operandType, TypeFlags.ESSymbolLike)) {
                //     error(node.operand, Diagnostics.The_0_operator_cannot_be_applied_to_type_symbol, tokenToString(node.operator));
                // }
                if (node.operator === SyntaxKind.PlusToken) {
                    if (maybeTypeOfKindConsideringBaseConstraint(operandType, TypeFlags.FloatLiteral)) {
                        error(node.operand, Diagnostics.Operator_0_cannot_be_applied_to_type_1, tokenToString(node.operator), typeToString(getBaseTypeOfLiteralType(operandType)));
                    }
                    return numberType;
                }
                return getUnaryResultType(operandType);
            case SyntaxKind.ExclamationToken:
                checkTruthinessOfType(operandType, node.operand);
                const facts = getTypeFacts(operandType, TypeFacts.Truthy | TypeFacts.Falsy);
                return facts === TypeFacts.Truthy ? falseType :
                    facts === TypeFacts.Falsy ? trueType :
                    booleanType;
            case SyntaxKind.PlusPlusToken:
            case SyntaxKind.MinusMinusToken:
                const ok = checkArithmeticOperandType(node.operand, checkNonNullType(operandType, node.operand), Diagnostics.An_arithmetic_operand_must_be_of_type_any_number_bigint_or_an_enum_type);
                if (ok) {
                    // run check only if former checks succeeded to avoid reporting cascading errors
                    checkReferenceExpression(
                        node.operand,
                        Diagnostics.The_operand_of_an_increment_or_decrement_operator_must_be_a_variable_or_a_property_access,
                        Diagnostics.The_operand_of_an_increment_or_decrement_operator_may_not_be_an_optional_property_access,
                    );
                }
                return getUnaryResultType(operandType);
        }
        return errorType;
    }

    function getUnaryResultType(operandType: Type): Type {
        if (maybeTypeOfKind(operandType, TypeFlags.FloatLiteral)) {
            return isTypeAssignableToKind(operandType, TypeFlags.AnyOrUnknown) || maybeTypeOfKind(operandType, TypeFlags.NumberLike)
                ? intType
                : floatType;
        }
        // If it's not a bigint type, implicit coercion will result in a number
        return numberType;
    }

